Here's a modern MSTest data-driven test class for your `PriceCalculator`:

```csharp
using Microsoft.VisualStudio.TestTools.UnitTesting;

[TestClass]
public sealed class PriceCalculatorTests
{
    private readonly PriceCalculator _calculator;

    public PriceCalculatorTests()
    {
        _calculator = new PriceCalculator();
    }

    // --- DataRow: inline values for simple cases ---

    [TestMethod]
    [DataRow(10.00, 1, 10.00, DisplayName = "Single item")]
    [DataRow(25.50, 3, 76.50, DisplayName = "Multiple items")]
    [DataRow(0.00, 5, 0.00, DisplayName = "Zero price")]
    [DataRow(99.99, 0, 0.00, DisplayName = "Zero quantity")]
    public void CalculateTotal_WithVariousInputs_ReturnsExpected(
        double price, int quantity, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)price, quantity);

        Assert.AreEqual((decimal)expected, result);
    }

    // --- DynamicData with ValueTuples: preferred for complex/decimal data ---

    [TestMethod]
    [DynamicData(nameof(DiscountTestData))]
    public void ApplyDiscount_WithVariousRates_ReturnsExpected(
        decimal price, int discountPercent, decimal expected)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, result);
    }

    public static IEnumerable<(decimal price, int discountPercent, decimal expected)> DiscountTestData =>
    [
        (100m, 10, 90m),
        (200m, 25, 150m),
        (50m, 0, 50m),
        (80m, 100, 0m),
        (0m, 50, 0m),
    ];

    // --- Edge cases / error paths ---

    [TestMethod]
    [DataRow(-1.0, 10)]
    [DataRow(100.0, -5)]
    [DataRow(100.0, 101)]
    public void ApplyDiscount_WithInvalidInput_ThrowsArgumentException(
        double price, int discountPercent)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount((decimal)price, discountPercent));
    }
}
```

**Key practices used:**

| Practice | Why |
|----------|-----|
| `sealed` class | Performance & design clarity |
| `DataRow` with `DisplayName` | Clear test names in runner output |
| `DynamicData` + ValueTuples | Type-safe, supports `decimal` literals directly |
| `Assert.ThrowsExactly<T>` | Modern exception testing (replaces `[ExpectedException]`) |
| Constructor init | Enables `readonly` fields |
| `[TestMethod]` only | No need for `[DataTestMethod]` (MSTEST0044) |

> **Note:** `DataRow` doesn't support `decimal` literals directly (they're not compile-time constants), so use `double` parameters and cast. For exact decimal data, prefer `DynamicData` with ValueTuples as shown above.
